param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'type-signature-method-lookup-boundaries-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
function Value($value,$self){if($null -eq $value){return $null};if($value -is [Type]){if([object]::ReferenceEquals($value,$self)){return 'self'};return 'type:'+$value.ToString()};if($value -is [bool]){return $value.ToString().ToLowerInvariant()};if($value -is [Enum]){return ([int]$value).ToString()};if($value -is [Array]){return (($value|ForEach-Object {Value $_ $self})-join ';')};return $value.ToString()}
function Resolve($name){$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$dict=[object].Assembly.GetType('System.Collections.Generic.Dictionary`2');$nullable=[object].Assembly.GetType('System.Nullable`1');switch($name){'null'{return $null};'ListD'{return $list};'DictD'{return $dict};'NullableD'{return $nullable};'TupleD'{return [object].Assembly.GetType('System.ValueTuple`2')};'ListS'{return $list.MakeGenericType([type[]]@([string]))};'Sig0'{return [Type]::MakeGenericMethodParameter(0)};'Sig1'{return [Type]::MakeGenericMethodParameter(1)};'Sig0Array'{return [Type]::MakeGenericMethodParameter(0).MakeArrayType()};'Sig0Ref'{return [Type]::MakeGenericMethodParameter(0).MakeByRefType()};'SigList'{return [Type]::MakeGenericSignatureType($list,[type[]]@([Type]::MakeGenericMethodParameter(0)))};default{return [Type]::GetType('System.'+$name,$true,$false)}}}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new()
foreach($case in $plan.cases){$type=[object].Assembly.GetType('System.'+$case.owner);$arguments=$null;if($null -ne $case.arguments){$arguments=[Type[]]::new($case.arguments.Count);for($i=0;$i -lt $arguments.Length;$i++){if($null -ne $case.arguments[$i]){$arguments[$i]=Resolve $case.arguments[$i]}}};$value=$null;$errorName='none';$message=$null;$hResult=0;$param=$null;try{if($null -eq $case.flags){$method=[Type].GetMethod('GetMethod',[Type[]]@([string],[Type[]]));$invoke=[object[]]::new(2);$invoke[0]=$case.name;$invoke[1]=$arguments}else{$method=[Type].GetMethod('GetMethod',[Type[]]@([string],[Reflection.BindingFlags],[Type[]]));$invoke=[object[]]::new(3);$invoke[0]=$case.name;$invoke[1]=[Reflection.BindingFlags]$case.flags;$invoke[2]=$arguments};$found=$method.Invoke($type,$invoke);if($null -ne $found){$value=$found.Name+'|'+$found.DeclaringType.FullName+'|'+$found.ReturnType.FullName+'|'+(($found.GetParameters()|ForEach-Object {$_.ParameterType.FullName})-join ';')}}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{id=$case.id;valueUnits=(Units $value);exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param)})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS typed method lookup capture: $($rows.Count) calls"
